PROOF_EXPORTS = sorted(set(re.findall(r'"ExportAs": "([^"]+)"', "".join(t for p, t in ASSETS.items() if "SkyWynn_P3_" in p))))
assert len(PROOF_EXPORTS) == len(P["islands"]) + 2 * len(P_JOINS) + 4 + 8, PROOF_EXPORTS   # 0.4: Depth, Above, LavaOK2D, Band3OK2D, CaveOK2D, WormPath2D, Entrance2D, Caves
_used_types = set(re.findall(r'"Type": "([^"]+)"', "".join(t for p, t in ASSETS.items() if "SkyWynn_P3_" in p or "SkyWynn_Proof" in p)))
