# ---- the 0.3 asset ids against Assets.zip: no vanilla clash, every vanilla id referenced exists (the 0.1 checks below cover the rest)
with zipfile.ZipFile(os.path.join(B.HYTALE, "install", "release", "package", "game", "latest", "Assets.zip")) as _azp:
    _np = _azp.namelist()
    for _env in [v[0] for v in PROOF_LOOKS.values()] + [P["void_env"]] + [e for v in CAVE_ENVS.values() for e in v]:
        assert any(n.startswith("Server/Environments/") and n.endswith("/%s.json" % _env) for n in _np), "environment " + _env
    for _v in PROOF_LOOKS.values():
        for _pp, _w in _v[6]:
            assert any(n.startswith("Server/Prefabs/%s/" % _pp) and n.endswith(".prefab.json") for n in _np), "prefab folder " + _pp
    assert not any(n.startswith("Server/Instances/%s/" % P["template"]) for n in _np), "vanilla instance name clash"
    assert sorted(CAVE_ENVS) == sorted(PROOF_LOOKS), "every look has its cave environments"
    assert any(n.startswith("Server/Item/Items/") and n.endswith("/%s.json" % CAVES["rock3"]) for n in _np), "block id " + CAVES["rock3"]
    assert any(n.startswith("Server/Item/Block/Fluids/") and n.endswith("/%s.json" % CAVES["lava"]) for n in _np), "fluid id " + CAVES["lava"]
    # the lava material spelling = vanilla's own (Volcanic1_Caldera: {"Solid": "", "Fluid": "Lava_Source"} in a FieldFunction delimiter)
    assert '"Solid":"","Fluid":"Lava_Source"' in re.sub(r"\s", "", _azp.read("Server/HytaleGenerator/Biomes/Volcanic1/Volcanic1_Caldera.json").decode("utf-8"))
    _vexp = set()
    for _n in _np:
        if _n.startswith("Server/HytaleGenerator/") and _n.endswith(".json"):
            for _m in re.finditer(r'"ExportAs"\s*:\s*"([^"]+)"', _azp.read(_n).decode("utf-8", "replace")):
                _vexp.add(_m.group(1))
    assert not (set(PROOF_EXPORTS) & _vexp), "proof export names must be ours"
# every node type the proof uses is a registered HytaleGenerator asset type name (the release jar's AssetManager constant pool)
with zipfile.ZipFile(B.SERVER_JAR) as _sj:
    _amc = _sj.read("com/hypixel/hytale/builtin/hytalegenerator/assets/AssetManager.class")
for _ty in ("XValue", "ZValue", "Sqrt", "Multiplier", "Max", "FieldFunction", "SimpleHorizontal", "DensityDelimited", "SimplexNoise3D", "Mix", "Cache"):
    assert (b"\x01" + len(_ty).to_bytes(2, "big") + _ty.encode()) in _amc, "node type %s is not registered by the V2 AssetManager" % _ty
print("0.3 + 0.4 proof assets (caves + lava): %d islands, %d joins (%s), %d exports, node types %s"
      % (len(P["islands"]), len(P_JOINS), ", ".join("%s %s-%s %.1f" % (j[0][0], j[0][1], j[0][2], j[5]) for j in P_JOINS), len(PROOF_EXPORTS),
         ", ".join(PROOF_NODE_TYPES)))

