M(isl, r"""
public static double hash(int ix, int iz, int salt) {
  int h = ix * 374761393 + iz * 668265263 + salt * 1442695041;
  h = (h ^ (h >>> 13)) * 1274126177;
  h = h ^ (h >>> 16);
  return (double) (h & 16777215) / 8388607.5 - 1.0;
}""")
M(isl, r"""
public static double vnoise(double x, double z, double scale, int salt) {
  double fx = x / scale;
  double fz = z / scale;
  double flx = Math.floor(fx);
  double flz = Math.floor(fz);
  int ix = (int) flx;
  int iz = (int) flz;
  double tx = fx - flx;
  double tz = fz - flz;
  tx = tx * tx * (3.0 - 2.0 * tx);
  tz = tz * tz * (3.0 - 2.0 * tz);
  double a = hash(ix, iz, salt);
  double b = hash(ix + 1, iz, salt);
  double c = hash(ix, iz + 1, salt);
  double d = hash(ix + 1, iz + 1, salt);
  double ab = a + (b - a) * tx;
  double cd = c + (d - c) * tx;
  return ab + (cd - ab) * tz;
}""")
M(isl, "public static double wob(double rx, double rz) { return WA1 * vnoise(rx, rz, WS1, 11) + WA2 * vnoise(rx, rz, WS2, 23); }")
# out[0] = the island u (wobbled distance / R; 9 = on no island), out[1] = the deepest join depth under the ground (0 = no join)
M(isl, r"""
public static boolean member(double rx, double rz, double[] out) {
  double w = wob(rx, rz);
  double bu = 9.0;
  for (int i = 0; i < I_CX.length; i++) {
    double dx = rx - I_CX[i];
    double dz = rz - I_CZ[i];
    double u = (Math.sqrt(dx * dx + dz * dz) + w) / I_R[i];
    if (u < bu) bu = u;
  }
  boolean on = bu <= 1.0;
  double jd = 0.0;
  for (int j = 0; j < J_KIND.length; j++) {
    double px = rx - J_AX[j];
    double pz = rz - J_AZ[j];
    double sa = px * J_UX[j] + pz * J_UZ[j];
    double q = Math.abs(pz * J_UX[j] - px * J_UZ[j]);
    double sp = J_SPAN[j];
    int k = J_KIND[j];
    if (k == 0) {
      if (q <= NECK_HALF && sa + INS >= 0.0 && sa <= sp + INS) jd = Math.max(jd, NECK_THICK);
    } else if (k == 1) {
      if (sa >= 0.0 && sa <= sp && q <= MOAT) on = false;
      if (q <= ARCH_HALF && sa + INS >= 0.0 && sa <= sp + INS) {
        double m = Math.abs(sa - sp / 2.0) / (sp / 2.0);
        if (m > 1.0) m = 1.0;
        jd = Math.max(jd, ARCH_MID + (ARCH_END - ARCH_MID) * m);
      }
    } else {
      if (sa >= 0.0 && sa < sp && q <= MOAT) on = false;
      if (q <= BH_HALF && ((sa + INS >= 0.0 && sa < 0.0) || (sa >= sp && sa <= sp + INS))) jd = Math.max(jd, BH_THICK);
    }
  }
  out[0] = on ? bu : 9.0;
  out[1] = jd;
  return on || jd > 0.0;
}""")
# the underside y of an island column (blocks below it are removed); h = vanilla's terrain height there
M(isl, r"""
public static int bottomOf(double[] m, int h, double rx, double rz) {
  double b = 1.0E9;
  if (m[0] <= 1.0) {
    double u = m[0];
    if (u <= KEEL_U) b = KEEL;
    else {
      double t = (u - KEEL_U) / (1.0 - KEEL_U);
      if (t > 1.0) t = 1.0;
      double sm = t * t * (3.0 - 2.0 * t);
      double v = KEEL + (RIM_BOT - KEEL) * sm + RA * vnoise(rx, rz, RS, 37) * sm;
      b = Math.min(v, (double) h - MIN_THICK);
    }
  }
  if (m[1] > 0.0) b = Math.min(b, (double) h - m[1]);
  if (b < KEEL) b = KEEL;
  return (int) Math.floor(b);
}""")
# a chunk with no island column at all (conservative: every island + wobble, every join strip + the chunk's half diagonal)
M(isl, r"""
public static boolean chunkOutside(int cx, int cz, double ox, double oz) {
  double x0 = cx * 32.0 - ox;
  double z0 = cz * 32.0 - oz;
  double x1 = x0 + 32.0;
  double z1 = z0 + 32.0;
  for (int i = 0; i < I_CX.length; i++) {
    double nx = Math.max(x0, Math.min(I_CX[i], x1));
    double nz = Math.max(z0, Math.min(I_CZ[i], z1));
    double dx = I_CX[i] - nx;
    double dz = I_CZ[i] - nz;
    if (Math.sqrt(dx * dx + dz * dz) <= I_R[i] + WOBMAX + 2.0) return false;
  }
  double mx = x0 + 16.0;
  double mz = z0 + 16.0;
  for (int j = 0; j < J_KIND.length; j++) {
    double px = mx - J_AX[j];
    double pz = mz - J_AZ[j];
    double sa = px * J_UX[j] + pz * J_UZ[j];
    double q = Math.abs(pz * J_UX[j] - px * J_UZ[j]);
    double half = J_KIND[j] == 0 ? NECK_HALF : (J_KIND[j] == 1 ? ARCH_HALF : BH_HALF);
    if (sa + INS + 24.0 >= 0.0 && sa <= J_SPAN[j] + INS + 24.0 && q <= half + 24.0) return false;
  }
  return true;
}""")
M(isl, r"""
public static void ids() {
  if (IDS) return;
  int st = -1;
  int ev = -1;
  try { st = @BT@.getAssetMap().getIndexOrDefault(SEAL, -1); } catch (Throwable t) { st = -1; }
  try { ev = @ENV@.getAssetMap().getIndexOrDefault(VOID_ENV, -1); } catch (Throwable t) { ev = -1; }
  STONE = st;
  ENVV = ev;
  FLE = @FL@.EMPTY_ID;
  IDS = true;
  if (st < 0 && @PKG@.WgLog.once("nostone")) @PKG@.WgLog.error("vanilla islands: block " + SEAL + " is not loaded - the underside skin can only drain fluids (no stone) until it is");
}""")
M(isl, r"""
public static int fluidAt(@FS@[] fs, int lx, int y, int lz) {
  @FS@ f = fs[y >> 5];
  return f == null ? FLE : f.getFluidId(lx, y, lz);
}""")
M(isl, r"""
public static void clearVoxel(@GC@ gc, @GBC@ bc, @FS@[] fs, int lx, int y, int lz) {
  int b = bc.getBlock(lx, y, lz);
  if (b != 0) {
    if (gc.getState(lx, y, lz) != null) gc.setState(lx, y, lz, null);
    bc.setBlock(lx, y, lz, 0, 0, 0);
    CLEARED.incrementAndGet();
  }
  @FS@ f = fs[y >> 5];
  if (f != null && f.getFluidId(lx, y, lz) != FLE) f.setFluid(lx, y, lz, FLE, (byte) 0);
}""")
M(isl, r"""
public static void clearColumn(@GC@ gc, @GBC@ bc, @FS@[] fs, int lx, int lz, int y0, int y1) {
  if (y1 > 320) y1 = 320;
  for (int sy = y0 >> 5; sy < 10 && sy * 32 < y1; sy++) {
    if (bc.getSection(sy * 32) == null && fs[sy] == null) continue;
    int a = Math.max(y0, sy * 32);
    int e = Math.min(y1, sy * 32 + 32);
    for (int y = a; y < e; y++) clearVoxel(gc, bc, fs, lx, y, lz);
  }
}""")
M(isl, r"""
public static void sealVoxel(@GC@ gc, @GBC@ bc, @FS@[] fs, int lx, int y, int lz) {
  @FS@ f = fs[y >> 5];
  if (f != null && f.getFluidId(lx, y, lz) != FLE) f.setFluid(lx, y, lz, FLE, (byte) 0);
  if (STONE >= 0) {
    if (bc.getBlock(lx, y, lz) != 0 && gc.getState(lx, y, lz) != null) gc.setState(lx, y, lz, null);
    bc.setBlock(lx, y, lz, STONE, 0, 0);
  }
  SEALED.incrementAndGet();
}""")
# the mask pass on one generated vanilla chunk (local x / z 0..31); hs = vanilla's terrain height (x, z) -> y
M(isl, r"""
public static int maskWith(@GC@ gc, int cx, int cz, double ox, double oz, java.util.function.IntBinaryOperator hs) {
  if (gc == null) return 0;
  ids();
  int bx = cx * 32;
  int bz = cz * 32;
  int[] bot = new int[34 * 34];
  int[] hh = new int[34 * 34];
  double[] mb = new double[2];
  int nin = 0;
  for (int i = 0; i < 34; i++) {
    for (int k = 0; k < 34; k++) {
      int x = bx + i - 1;
      int z = bz + k - 1;
      double rx = x + 0.5 - ox;
      double rz = z + 0.5 - oz;
      int idx = i * 34 + k;
      if (member(rx, rz, mb)) {
        int h = hs.applyAsInt(x, z);
        hh[idx] = h;
        bot[idx] = bottomOf(mb, h, rx, rz);
        if (i >= 1 && i <= 32 && k >= 1 && k <= 32) nin++;
      } else {
        bot[idx] = OUT;
        hh[idx] = 0;
      }
    }
  }
  @GBC@ bc = gc.getBlockChunk();
  @HOLD@[] secs = gc.getSections();
  @FS@[] fs = new @FS@[10];
  for (int sy = 0; sy < 10; sy++) {
    @HOLD@ hd = secs == null || sy >= secs.length ? null : secs[sy];
    fs[sy] = hd == null ? null : (@FS@) hd.getComponent(@FS@.getComponentType());
  }
  for (int lx = 0; lx < 32; lx++) {
    for (int lz = 0; lz < 32; lz++) {
      int idx = (lx + 1) * 34 + (lz + 1);
      int b = bot[idx];
      if (b >= OUT) {
        clearColumn(gc, bc, fs, lx, lz, 0, 320);
        if (ENVV >= 0) bc.setEnvironmentColumn(lx, lz, ENVV);
        continue;
      }
      if (b > 0) clearColumn(gc, bc, fs, lx, lz, 0, b);
      int nb = Math.max(Math.max(bot[idx - 34], bot[idx + 34]), Math.max(bot[idx - 1], bot[idx + 1]));
      int end = Math.min(320, Math.max(b + SHELL, nb));
      int skinTop = hh[idx] - SKIN_TOP;
      for (int y = b; y < end; y++) {
        boolean shell = y < b + SHELL;
        boolean side = y < bot[idx - 34] || y < bot[idx + 34] || y < bot[idx - 1] || y < bot[idx + 1];
        int fl = fluidAt(fs, lx, y, lz);
        if (fl != FLE) {
          if (shell || side) sealVoxel(gc, bc, fs, lx, y, lz);
        } else if (bc.getBlock(lx, y, lz) == 0 && (shell || (side && y < skinTop))) {
          sealVoxel(gc, bc, fs, lx, y, lz);
        }
      }
    }
  }
  java.util.List el = gc.getEntityChunk() == null ? null : gc.getEntityChunk().getEntities();
  if (el != null) {
    java.util.Iterator it = el.iterator();
    while (it.hasNext()) {
      Object o = it.next();
      if (!(o instanceof @EWE@)) continue;
      @V3I@ v = ((@EWE@) o).offset();
      if (v == null) continue;
      double rx = v.x + 0.5 - ox;
      double rz = v.z + 0.5 - oz;
      boolean keep = member(rx, rz, mb) && v.y >= bottomOf(mb, hs.applyAsInt(v.x, v.z), rx, rz);
      if (!keep) { it.remove(); ENTS.incrementAndGet(); }
    }
  }
  return nin;
}""")
M(isl, r"""
public static @GC@ emptyChunk(long index, int cx, int cz) {
  ids();
  @GC@ g = new @GC@();
  g.getBlockChunk().setCoordinates(index, cx, cz);
  if (ENVV >= 0) {
    for (int x = 0; x < 32; x++) for (int z = 0; z < 32; z++) g.getBlockChunk().setEnvironmentColumn(x, z, ENVV);
  }
  return g;
}""")

