# ================================================================= plugin
C(pl, "public SkyyWorldGenPlugin(@JPI@ init) { super(init); }")
M(pl, r"""
public void setup() {
  @PKG@.WgLog.LOG = getLogger();
  java.nio.file.Path dir = getDataDirectory().resolveSibling("Skyy_SkyyWorldGen");
  @PKG@.WgCfg.DIR = dir;
  @PKG@.WgCfg.FILE = dir.resolve("config.properties");
  @PKG@.WgStore.FILE = dir.resolve("worlds.properties");
  @PKG@.WgCfg.load();
  @PKG@.WgStore.read();
  try {
    getCodecRegistry(@IWGP@.CODEC).register(@PKG@.WgIsle.TYPE, @PKG@.WgIsleProvider.class, @PKG@.WgIsleProvider.CODEC);
    @PKG@.WgIsle.REGISTERED = true;
  } catch (Throwable t) {
    @PKG@.WgLog.error("could not register the island world generator type " + @PKG@.WgIsle.TYPE + ": " + t + " - /zone proof refuses, a saved " + @PKG@.WgZones.WORLDS[@PKG@.WgZones.PROOF] + " cannot load");
  }
  @PKG@.WgZoneIsles.LAYDIR = dir;
  try {
    getCodecRegistry(@IWGP@.CODEC).register(@PKG@.WgZoneIsles.TYPE, @PKG@.WgZoneProvider.class, @PKG@.WgZoneProvider.CODEC);
    @PKG@.WgZoneIsles.REGISTERED = true;
  } catch (Throwable t) {
    @PKG@.WgLog.error("could not register the zone islands world generator type " + @PKG@.WgZoneIsles.TYPE + ": " + t + " - /zone 1-5 refuse, a saved " + @PKG@.WgZones.WORLDS[@PKG@.WgZones.ZONES] + " cannot load");
  }
  getCommandRegistry().registerCommand(new @PKG@.ZoneCmd());
  getEventRegistry().registerGlobal(@PRE@.class, new @PKG@.WgReady());
  getEventRegistry().registerGlobal(@PRE@.class, new @PKG@.WgZoneArrive());
  String made = @PKG@.WgStore.createdText(@PKG@.WgZones.WORLDS[0]);
  String pmade = @PKG@.WgStore.createdText(@PKG@.WgZones.WORLDS[@PKG@.WgZones.PROOF]);
  String zmade = @PKG@.WgStore.createdText(@PKG@.WgZones.WORLDS[@PKG@.WgZones.ZONES]);
  @PKG@.WgLog.info("@VERSION@ ready (@KITID@) - TEST VERSION: /zone, /zone 1-5, /zone old, /zone proof, /zone info | leave | setlanding | reload for admins only (@NODE@); " + @PKG@.WgCfg.LOADED + "; ZONE ISLANDS = world " + @PKG@.WgZones.WORLDS[@PKG@.WgZones.ZONES] + " (" + (zmade == null ? "not created yet" : "made " + zmade) + "), template " + @PKG@.WgZones.TEMPLATES[@PKG@.WgZones.ZONES] + " " + (@PKG@.WgCheck.templateOk(@PKG@.WgZones.ZONES) ? "found" : "NOT FOUND") + ", generator type " + @PKG@.WgZoneIsles.TYPE + (@PKG@.WgZoneIsles.REGISTERED ? " registered" : " NOT REGISTERED") + ", seed " + @PKG@.WgZoneIsles.SEED + "; old Zone 1 test island = world " + @PKG@.WgZones.WORLDS[0] + " (" + (made == null ? "not created yet" : "made " + made) + "), template " + @PKG@.WgZones.TEMPLATES[0] + " " + (@PKG@.WgCheck.templateOk(0) ? "found" : "NOT FOUND - check Server/Instances in the jar") + ", structure " + @PKG@.WgZones.STRUCTURES[0] + " (checked at the first /zone); vanilla islands proof = world " + @PKG@.WgZones.WORLDS[@PKG@.WgZones.PROOF] + " (" + (pmade == null ? "not created yet" : "made " + pmade) + "), template " + @PKG@.WgZones.TEMPLATES[@PKG@.WgZones.PROOF] + " " + (@PKG@.WgCheck.templateOk(@PKG@.WgZones.PROOF) ? "found" : "NOT FOUND") + ", generator type " + @PKG@.WgIsle.TYPE + (@PKG@.WgIsle.REGISTERED ? " registered" : " NOT REGISTERED") + " (the 0.4 proof world skywynn_proof, if any, is kept as it is); settings in Server Setup > World Gen; data in " + dir);
  @PKG@.CfgPub.start(getDataDirectory().getParent(), getLogger());
}""")
M(pl, r"""
protected void shutdown() {
  try { @PKG@.CfgPub.shutdown(); } catch (Throwable t) { }
  super.shutdown();
}""")

